  CollectionHall_100310_Title = {
    Text = "Día polar eterno"
  },
  CollectionHall_100442_Desc = {
    Text = "<Title:Introducción>\nnació en una familia de ricos humanos, pero corre por sus venas la sangre de un ghoul. La mezcla de su linaje humano y ghoul le otorgó un talento único, permitiéndole ver un mundo que los demás no pueden. Ese mundo es loco, absurdo, y los colores deslumbrantes lo atrapan. \nSin dudarlo, Pickman eligió registrar con su pincel todo lo que veía. Se sumergió en ello, y con el paso de los días, adquirió una habilidad pictórica magistral. \nLa estética convencional rechazó por completo a Pickman; nadie podía aceptar su locura. A menudo se sentía triste por ello, pero nunca se rindió. \nFinalmente, Pickman abrazó la fusión y despertó por completo la sangre de ghoul que llevaba dentro. Dejó el mundo humano y llegó a la ciudad del rey ghoul. Un día, presentará ante el mundo todas las escenas fantásticas y locas del verdadero mundo."
  },
  CollectionHall_100442_LockTip = {
    Text = "Desbloqueado al despertar a\"Pickman\""
  },
  CollectionHall_100442_Title = {Text = "Pickman"},
  CollectionHall_100458_Desc = {
    Text = "Deja tus preocupaciones de lado por ahora y deja que lafatiga se disipe rápidamente. \n Tomemos un breve descanso junto a la cálida hoguera."
  },
  CollectionHall_100458_LockTip = {
    Text = "Completar el errante \"El día inmortal\""
  },
  CollectionHall_100458_Title = {
    Text = "Respiro junto al fuego"
  },
  CollectionHall_100459_Desc = {
    Text = "Quema, quema, deja que todo lo que te pertenece se queme por completo. \n Entonces en esa llama interminable, ¡comienza tu funeral con el mundo!"
  },
  CollectionHall_100459_LockTip = {
    Text = "Completar el errante \"El día inmortal\""
  },
  CollectionHall_100459_Title = {
    Text = "Funeral en llamas"
  },
  CollectionHall_100460_Desc = {
    Text = "\"Lo he dicho antes, no importa los medios, traeré a todos a casa.\"\n\"Quemaré todo lo que me pertenece, y luego...\n\"Con este infierno de las estrellas, quemaré este mundo falso, sucio y caótico hasta cenizas!\"\n\"¡Lo declaro en nombre de Kathigu-Ra!\"\n\"¡La aurora vendrá!\""
  },
  CollectionHall_100460_LockTip = {
    Text = "Completar el errante \"El día inmortal\""
  },
  CollectionHall_100460_Title = {
    Text = "El amanecer que quema todo"
  },
  CollectionHall_100461_Desc = {
    Text = "La locura de la muerte gira como un caleidoscopio, el dulce olor metálico que surge de la enfermedad y los cadáveres es el mejor incienso. Levantas tus copas desde lejos, separados por innumerables almas que se dirigen a su perdición—si la muerte está destinada, dejemos que apresurémonos alegremente a este baile, y juntos, con el último latido de la danza, zambullámonos en las puertas del Infierno."
  },
  CollectionHall_100461_LockTip = {
    Text = "Completa \"Banquete Ardiente\" en dificultad Difícil en La Errante"
  },
  CollectionHall_100461_Title = {
    Text = "Vino, flores y muerte gloriosa"
  },
  CollectionHall_100462_Desc = {
    Text = "Hace mucho, mucho tiempo, ella fue la soberana dictatorial del universo, y todo lo que veía pertenecía a sus súbditos.\nMucho, mucho tiempo después, todo lo que podía ver en sus ojos era polvo infinito, y desde entonces, todo lo que gobernaba era desolación y soledad."
  },
  CollectionHall_100462_LockTip = {
    Text = "Completa \"Banquete Ardiente\" en La Errante"
  },
  CollectionHall_100462_Title = {
    Text = "Reina de la desolación"
  },
  CollectionHall_100463_Desc = {
    Text = "Ella es desenfrenada, violenta y caprichosa, pero también es benévola, erudita y llena de sabiduría. \n Ella es la tirana de la depravación y la protectora de los corderos; te concede amor y también te concede muerte. Todos los seres vivos en esta tierra deben arrastrarse a sus pies, llamando respetuosamente su nombre. \n Sumérgete en el baile de la Reina, y luego con ella, hundirte en la eterna llama negra."
  },
  CollectionHall_100463_LockTip = {
    Text = "Completa \"Banquete Ardiente\" en La Errante"
  },
  CollectionHall_100463_Title = {
    Text = "Un brindis por la muerte"
  },
  CollectionHall_100464_Desc = {
    Text = "Si solo puedes hacer una última cosa antes de morir, entonces baila.\nBebe el dulce vino, traga la deliciosa carne asada y gira libremente en el festín de la música.\nDeja que el último reflejo de este mundo en tus ojos aún brille con una luz dorada embriagadora."
  },
  CollectionHall_100464_LockTip = {
    Text = "Completa \"Banquete Ardiente\" en dificultad Difícil en La Errante"
  },
  CollectionHall_100464_Title = {
    Text = "Máscara de la plaga"
  },
  CollectionHall_100465_Desc = {
    Text = "Ella siempre ve el glorioso pasado en el lago.\nLos recuerdos desgastados son como falsos sueños; en el sueño, ella se sienta en medio de ruinas infinitas, presenciando cómo todo lo que le pertenece se desvanece como fantasmas.\nCuando incluso ese sueño sea olvidado, el flautista vendrá a través de la niebla, guiándola hacia el camino de regreso para los que se han ido."
  },
  CollectionHall_100465_LockTip = {
    Text = "Completa \"Banquete Ardiente\" en La Errante"
  },
  CollectionHall_100465_Title = {
    Text = "Reflejo en el lago"
  },
  CollectionHall_100466_Desc = {
    Text = "La existencia eterna entre las estrellas abre sus ojos una vez más, lanzando su poder inmortal sobre este planeta turbio, sucio y, sin embargo, increíblemente azul, \n tal como lo hizo cuando el sol brilló hace cuatro mil millones de años."
  },
  CollectionHall_100466_LockTip = {
    Text = "Completar el errante \"El día inmortal\""
  },
  CollectionHall_100466_Title = {
    Text = "Reencuentro después de cuarenta mil millones de años"
  },
