  },
  CollectionHall_117957_Title = {
    Text = "Historia de fantasmas"
  },
  CollectionHall_117958_Desc = {
    Text = "Ella se desvanece más allá de la memoria y el pasado, cruza el lodazal de la muerte y la vida, reuniéndose en silencio contigo."
  },
  CollectionHall_117958_LockTip = {
    Text = "Desbloquear al completar la investigación 7-19"
  },
  CollectionHall_117958_Title = {
    Text = "Reencuentro en el ataúd"
  },
  CollectionHall_117959_Desc = {
    Text = "La poesía, las emociones, los recuerdos, la moral... todo es un estorbo. Este concepto, los poetas nunca lo entienden."
  },
  CollectionHall_117959_LockTip = {
    Text = "Completa el registro especial \"Hábito de la Rosa\" en dificultad Difícil"
  },
  CollectionHall_117959_Title = {
    Text = "Cité Festival"
  },
  CollectionHall_117960_Desc = {
    Text = "Ella insiste en actuar sola, o te disparará. \n Pero al final, ganó un buen estudiante, y también un lobo."
  },
  CollectionHall_117960_LockTip = {
    Text = "Completar Mundo de Sueños Extraños\"Adiós Nunca Jamás\""
  },
  CollectionHall_117960_Title = {
    Text = "Espectáculo de un solo hombre"
  },
  CollectionHall_117961_Desc = {
    Text = "¡Come, Efe! ¡Mira, Efe!\n¡Un puente construido entre la locura y la realidad por colores y arte!\n¡Solo estamos los dos aquí, solo nosotros podemos ver la verdad!"
  },
  CollectionHall_117961_LockTip = {
    Text = "Completar el errante \"Pintura de aberración\""
  },
  CollectionHall_117961_Title = {
    Text = "¡Bienvenido, Efe!"
  },
  CollectionHall_117962_Desc = {
    Text = "Cada vez que escribe un versículo, florece un pétalo, piensa. \n Riega las frases con su vida, cuando el último salmo esté terminado, podrán regresar al jardín del pasado."
  },
  CollectionHall_117962_LockTip = {
    Text = "Completa el registro especial \"Hábito de la Rosa\" en dificultad Difícil"
  },
  CollectionHall_117962_Title = {
    Text = "El último salmo"
  },
  CollectionHall_117963_Desc = {
    Text = "Él ha decidido dejar este lado e ir al otro. \nDespídete de él, pero no lo olvides. \nÉl te recordará, te observará, ese loco rebelde, el genio pintor, y la luna que cuelga en el cielo nocturno."
  },
  CollectionHall_117963_LockTip = {
    Text = "Completar el errante \"Pintura de aberración\""
  },
  CollectionHall_117963_Title = {Text = "Ve allí"},
  CollectionHall_117964_Desc = {
    Text = "Canta en voz alta, baila, mientras la miel y la leche se entrelazan junto al fuego.\nEl final se acerca, con pies que suben, brazos entrelazados y cuellos inclinados para un beso—¡procrea! ¡Procrea! Bajo la sombra del árbol madre, eventualmente habrá descendencia que recibirá favor!"
  },
  CollectionHall_117964_LockTip = {
    Text = "Desbloquear al completar Investigación 7-19"
  },
  CollectionHall_117964_Title = {
    Text = "¡Reproducción, reproducción!"
  },
  CollectionHall_117965_Desc = {
    Text = "Véncenos, mátanos. Luego, sálvanos."
  },
  CollectionHall_117965_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Difícil 8-10"
  },
  CollectionHall_117965_Title = {
    Text = "El destino se acerca"
  },
  CollectionHall_117966_Desc = {
    Text = "Un brazo de una señorita está enhebrado a través de una cuerda elástica, y otra señorita que ha muerto dos veces, juntas, fabricaron un espectro falso."
  },
  CollectionHall_117966_LockTip = {
    Text = "Completa el registro especial \"¡Feliz Caza!\""
  },
  CollectionHall_117966_Title = {
    Text = "¡Te atrapé"
  },
  CollectionHall_117967_Desc = {
    Text = "El cuerpo de la reina fue atacado por la disolución, y el pueblo de Aram deambula por la arena amarilla. \nEl tiempo es testificado a través de las rendijas por los que han partido, testificando que el destino no pudo hacer nada contra Aram durante cientos de años."
  },
  CollectionHall_117967_LockTip = {
    Text = "Desbloquear Operación de investigación · Dificultad 7-12"
  },
  CollectionHall_117967_Title = {
    Text = "Testimonio de un siglo"
  },
  CollectionHall_117969_Desc = {
    Text = "Esa existencia innombrable, incontrolable, tonta y ciega. \n Ha emergido, está medio despierta, ha revelado su aterradora y colosal intimidación."
  },
  CollectionHall_117969_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Dificultad 8-10"
  },
  CollectionHall_117969_Title = {
    Text = "Autoridad contra dioses"
  },
  CollectionHall_117970_Desc = {
    Text = "Silencio, avanza. La obertura ya ha sido tocada. \n Te acompañaré hacia el capítulo final, destinado, supremo y más hermoso."
  },
  CollectionHall_117970_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación 8-14"
  },
  CollectionHall_117970_Title = {Text = "Gran Orden"},
  CollectionHall_117971_Desc = {
