  },
  CollectionHall_117973_Title = {
    Text = "El Caballero Virtuoso y el Troll"
  },
  CollectionHall_117974_Desc = {
    Text = "La antigua reina, la reina olvidada, aún espera en la infinita soledad. \nEsperando que su sangre y su linaje sean llevados hacia un nuevo mundo después de la aniquilación."
  },
  CollectionHall_117974_LockTip = {
