  },
  CollectionHall_117975_Desc = {
    Text = "El jardín es un rompecabezas, y la rosa es su respuesta."
  },
  CollectionHall_117975_LockTip = {
    Text = "Completa el registro especial \"El Hábitat de la Rosa\""
  },
  CollectionHall_117975_Title = {
    Text = "Un ramo para la primavera"
  },
  CollectionHall_117976_Desc = {
    Text = "La luz del sol se filtra a través del cristal del invernadero y cae sobre la cara de Horla. Ella atraviesa la luz del sol y se acerca a Horla, que está medio dormida. \nCada vez que la despierta, esconde la rosa detrás de su espalda."
  },
  CollectionHall_117976_LockTip = {
    Text = "Completa el registro especial \"El Hábitat de la Rosa\""
  },
  CollectionHall_117976_Title = {
    Text = "Amanecer en el invernadero"
  },
  CollectionHall_117977_Desc = {
    Text = "Ella escribió las historias del jardín en páginas de poema.\nElla arrojó las historias del jardín a la hoguera."
  },
  CollectionHall_117977_LockTip = {
    Text = "Completa el registro especial \"El Hábitat de la Rosa\""
  },
  CollectionHall_117977_Title = {
    Text = "Ceniza de Página de poema"
  },
  CollectionHall_117978_Desc = {
    Text = "Sin pobreza, hambre, enfermedad o traición. Esa es la Cité, donde solo hay flores y poesía, es un paraíso que les pertenece solo a ellas."
  },
  CollectionHall_117978_LockTip = {
    Text = "Completa el registro especial \"El Hábitat de la Rosa\""
  },
  CollectionHall_117978_Title = {
    Text = "Tierra de Fantasía"
  },
  CollectionHall_117979_Desc = {
    Text = "Si una pistola aparece en el primer acto, disparará al final.\nYa has concebido la historia para contarle en el reencuentro.\nEs un sueño, el comienzo del sueño deja caer un brillante sol, el final del sueño deja caer un sol negro como el carbón."
  },
  CollectionHall_117979_LockTip = {
    Text = "Completar Mundo de Sueños Extraños \"Adiós, Nunca Jamás\" en dificultad difícil"
  },
  CollectionHall_117979_Title = {Text = "Sol caído"},
  CollectionHall_117980_Desc = {
    Text = "¡El hidromiel se ha llenado, los distinguidos invitados han llegado, por favor traigan nuevas semillas para Lemvahi y disfruten de la pasión empapada en deseo!"
  },
  CollectionHall_117980_LockTip = {
    Text = "Desbloquear al completar la operación de investigación 7-19"
  },
  CollectionHall_117980_Title = {
    Text = "Momento de pasión"
  },
  CollectionHall_117981_Desc = {
    Text = "Tiempo, existencia, olvido, destino.\nTodos los sueños oscuros, la realidad vacía, se fusionan en la corriente por igual, desapareciendo sin dejar rastro, avanzando sin cesar, hacia el mar."
  },
  CollectionHall_117981_LockTip = {
    Text = "Completar Operación de investigación · Dificultad 7-12 Desbloqueado"
  },
  CollectionHall_117981_Title = {
    Text = "Regreso al mar"
  },
  CollectionHall_117982_Desc = {
    Text = "Ella pisa las ondas negras en la arena, te guía, te atrapa, trayendo diversas cosas de la desolación hacia ti.\nLa luna de esta noche oculta un hermoso secreto oscuro; ella responde a tus dudas en danza y te deja con más acertijos a través de un baile."
  },
  CollectionHall_117982_LockTip = {
    Text = "Desbloquear al completar Investigación 7-19"
  },
  CollectionHall_117982_Title = {
    Text = "Danza del mar de arenas plateadas"
  },
  CollectionHall_117983_Desc = {
    Text = "Indulga al rebelde, víctima de Sus caprichos malvados, que también comparte Sus malos hábitos."
  },
  CollectionHall_117983_LockTip = {
    Text = "Completa el registro especial \"¡Feliz Caza!\""
  },
  CollectionHall_117983_Title = {
    Text = "Copiar malos hábitos"
  },
  CollectionHall_117984_Desc = {
    Text = "El mal augurio y la melodía se entrelazan en la llegada, él es tanto enemigo como amigo, es esquivo."
  },
  CollectionHall_117984_LockTip = {
    Text = "Desbloquear al completar Operación de investigación 8-14"
  },
  CollectionHall_117984_Title = {
    Text = "La obertura del destino"
  },
  CollectionHall_117985_Desc = {
    Text = "Captura cada nota, cae en el ritmo correcto.\nTen cuidado, presta atención, enfréntate al exigente director; los errores pueden llevarte a una perdición irreversible."
  },
