  },
  CollectionHall_117985_Title = {
    Text = "Sigue el ritmo"
  },
  CollectionHall_117986_Desc = {
    Text = [[
Intercambia una rosa por un poema. 
 En los corazones desolados de las personas, las rosas habitan en un rojo intenso.]]
