  CollectionHall_117986_LockTip = {
    Text = "Completa el registro especial \"Hábito de la Rosa\" en dificultad Difícil"
  },
  CollectionHall_117986_Title = {
    Text = "Rosa, oh rosa"
  },
  CollectionHall_117987_Desc = {
    Text = "Hemos preparado unas vacaciones perfectas para ti, incluyendo playa, sol, partidos de voleibol, viejos amigos y nuevos amigos.\nPor favor, asegúrate de usar protector solar, si el sol cae del cielo, no entres en pánico, es algo normal."
  },
  CollectionHall_117987_LockTip = {
    Text = "Completar \"Adiós Nunca Jamás\""
  },
  CollectionHall_117987_Title = {
    Text = "Verano en Londinium"
  },
  CollectionHall_117988_Desc = {
    Text = "No eres bueno en la música ni disfrutas resolver acertijos.\nPero él te teje con calma y gracia en la sinfonía, lanzando sus acertijos de manera misteriosa y grosera."
  },
  CollectionHall_117988_LockTip = {
    Text = "Completar la Operación de investigación 8-14 para desbloquear"
  },
  CollectionHall_117988_Title = {
    Text = "El acertijo del director de orquesta"
  },
  CollectionHall_117989_Desc = {
    Text = "Pobre, arrogante y desinformado lobo. \n Él y otros huéspedes fueron arrojados a la sala de descanso, en una breve y pacífica partida de apuestas. \n Al perder su habitual buena suerte, perdió más de diez mil Leonian Florins."
  },
  CollectionHall_117989_LockTip = {
    Text = "Completa el registro especial \"¡Feliz Caza!\""
  },
  CollectionHall_117989_Title = {Text = "Carta mala"},
  CollectionHall_117990_Desc = {
    Text = "El mismo sombrero de copa, la misma rosa, la misma risa. \n El telón ya se ha levantado, el público ya está en su lugar, vamos, vamos, a buscar, ¿quién es el asesino que ha caído de la niebla negra?"
  },
  CollectionHall_117990_LockTip = {
    Text = "Completa el registro especial \"¡Feliz Caza!\""
  },
  CollectionHall_117990_Title = {Text = "Pequeño N"},
  CollectionHall_117991_Desc = {
    Text = "Los buenos días siempre comienzan con pesadillas y terminan en el cementerio.\nOh, así es la vida, dulce vida."
  },
  CollectionHall_117991_LockTip = {
    Text = "Completa el registro especial \"¡Feliz Caza!\" en dificultad Difícil"
  },
  CollectionHall_117991_Title = {
    Text = "Oh, la vida"
  },
  CollectionHall_117992_Desc = {
    Text = "Toma mi mano. \n Cuando nuestros dedos se toquen, te daré una primavera."
  },
  CollectionHall_117992_LockTip = {
    Text = "Completa el registro especial \"El Hábitat de la Rosa\""
  },
  CollectionHall_117992_Title = {
    Text = "Primavera de dos personas"
  },
  CollectionHall_117993_Desc = {
    Text = "Una visita repentina, una visita atenta, una visita feliz. \n Son amigos similares, son amigos diferentes. \n Oh, amigo, amigo, todos necesitan amigos. ¿Con qué te voy a recibir, amigo mío?"
  },
  CollectionHall_117993_LockTip = {
    Text = "Completar el errante \"Pintura de aberración\""
  },
  CollectionHall_117993_Title = {
    Text = "Amigos diferentes"
  },
  CollectionHall_117994_Desc = {
    Text = "La ruleta que salió de la tumba, persiguiendo incansablemente el pasado en una noche nevada. \n Juega una vez más, y otra, la piel del lobo y la buena suerte traerán un soleado lunes."
  },
  CollectionHall_117994_LockTip = {
    Text = "Completa el registro especial \"¡Feliz Caza!\""
  },
  CollectionHall_117994_Title = {
    Text = "Lunes de lobo"
  },
  CollectionHall_117995_Desc = {
    Text = "Los hijos de Aran han recorrido el gran desierto, nacen aquí, crecen aquí, están destinados a prosperar aquí y a desaparecer aquí."
  },
  CollectionHall_117995_LockTip = {
    Text = "Desbloquear al completar la operación de investigación 7-19"
  },
  CollectionHall_117995_Title = {
    Text = "El Camino de la Abundancia"
  },
  CollectionHall_117996_Desc = {
    Text = "Buen niño, querido bebé, el Río Sagrado calmará tus gemidos por la muerte prematura, el Río Sagrado sostendrá tu alma que ha transcurrido."
  },
  CollectionHall_117996_LockTip = {
    Text = "Desbloquear al completar la operación de investigación 7-19"
  },
  CollectionHall_117996_Title = {
    Text = "Devuelto al Río Sagrado"
