    Text = "Se puede desbloquear en el capítulo 4-5"
  },
  CollectionHall_120465_Title = {Text = "Crujido"},
  CollectionHall_120466_LockTip = {
    Text = "Se puede desbloquear en: Capítulo 3–10"
  },
  CollectionHall_120466_Title = {
    Text = "Telegrama Silencioso"
  },
  CollectionHall_121154_Title = {Text = "Paraíso"},
  CollectionHall_121341_Desc = {
    Text = "<Title:Introducción>\n La \"princesa\" que acepta el deber de gestar el \"Niño Santo\", ahora se ha convertido en la \"Madre Divina\" de gran importancia dentro de la secta de marineros.\n Ella también fue una dama que corría hacia la libertad, emprendiendo el viaje de escape en el Sonanir, al igual que Murphy, registrado por Misaq.\n Pero en un mundo sin el Guardián del secreto, el destino rompió el noble cuello del joven cisne.\n La sangre torcida se entrelaza con ella sin permitir resistencia, incluso si su cuerpo muere, no podrá escapar. Ella se esfuerza por mantener la compostura, repitiendo una y otra vez \"Soy la noble Madre Divina\", que es solo una auto-sugerencia y persuasión.\n Solo puede obedecer, solo obedecer. Obedecer los falsos oráculos, obedecer el absurdo destino, y luego, de la amarga eternidad, apenas saborear un toque de la dulce fantasía."
  },
  CollectionHall_121341_LockTip = {
    Text = "Desbloqueado al despertar a\"Delirio: Falso Engendro\""
  },
  CollectionHall_121341_Title = {
    Text = "Murphy: fauxborn"
  },
  CollectionHall_121381_Desc = {
    Text = "Intercambiaste mil bellotas por una historia de otro mundo. \n Una historia sobre héroes y demonios, sobre vigilancia y persistencia. \n Una historia de impotencia y renuencia, viejos amigos y nuevos amigos. \n Una historia que una vez llegó."
  },
  CollectionHall_121381_LockTip = {
    Text = "Completar la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121381_Title = {
    Text = "Eco de la Posada de los Mil Fenómenos"
  },
  CollectionHall_121382_Desc = {
    Text = "Largo, largo tiempo después, él y él finalmente tuvieron una balada que se difundió. \n Sobre la redención de la reanimación, sobre las almas gemelas."
  },
  CollectionHall_121382_LockTip = {
    Text = "Completar \"Mundo de Sueños Extraños: Más allá del horizonte·bajo\""
  },
  CollectionHall_121382_Title = {
    Text = "Poema de los pájaros sin alas"
  },
  CollectionHall_121383_Desc = {
    Text = "El joven pagó el precio que le fue reclamado por lo efímero de todo. \n Ahora, solo queda la autoridad silenciosa que lo acompaña. \n El rey está a punto de dormir, y en sus sueños da la bienvenida al fin del mundo."
  },
  CollectionHall_121383_LockTip = {
    Text = "Completar el errante \"Día de la coronación\""
  },
  CollectionHall_121383_Title = {
    Text = "El reino de la interminable tristeza y soledad"
  },
  CollectionHall_121384_Desc = {
    Text = "Ellas te rodean, te adoran, te acompañan.\nZarparon hacia el Dios Creador."
  },
  CollectionHall_121384_LockTip = {
    Text = "Completar la Operación de investigación 9-11 Desbloqueado"
  },
  CollectionHall_121384_Title = {
    Text = "Levanta velas hacia el Dios Creador"
  },
  CollectionHall_121385_Desc = {
    Text = "Eran unas alas renacidas de la destrucción, eran unas alas que compraron la libertad con sacrificio.\nLa profecía del destino ya se ha cumplido, él juró en su arrepentimiento que la deuda de sangre se pagará con sangre."
  },
  CollectionHall_121385_LockTip = {
    Text = "Completar \"Mundo de Sueños Extraños: Más allá del horizonte · bajo\""
  },
  CollectionHall_121385_Title = {
    Text = "Cuando se levanta la tormenta"
  },
  CollectionHall_121386_Desc = {
    Text = "Desde el inicio del absurdo y caótico sueño, Él estaba destinado a enfrentar su destino. \n Pero ha experimentado demasiado y ha definido demasiado. \n Él ha decidido observar su origen, esa deidad suprema, con la máxima razón que la humanidad puede mantener."
  },
  CollectionHall_121386_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación 9-11"
  },
  CollectionHall_121386_Title = {
    Text = "Guerra del Destino Primordial"
  },
  CollectionHall_121387_Desc = {
    Text = "Obtener, perder, cortar, sacrificio. \n El héroe pagó el precio total, el poder de proteger los tesoros es su recompensa."
  },
  CollectionHall_121387_LockTip = {
    Text = "Completar la Operación de investigación 9-13 desbloqueado"
  },
  CollectionHall_121387_Title = {
    Text = "Ojo sin Pupilo"
  },
  CollectionHall_121388_Desc = {
    Text = "Él se impuso la corona, y se impuso las cadenas. \n Esa era una cálida ilusión efímera, esa era la gloria pasada destinada a la destrucción."
  },
  CollectionHall_121388_LockTip = {
    Text = "Completar el errante \"Día de la coronación\""
  },
  CollectionHall_121388_Title = {
    Text = "El camino solitario del joven rey"
  },
  CollectionHall_121389_Desc = {
    Text = "A pesar de la situación adversa, la comisura de tu boca se ha levantado ligeramente.\n\"¡Mi turno, roba carta!\"\nYa sea en la Posada de Wanxiang o en Misaq,\nsubestimar la capacidad de daño de apoyo puede llevar a pérdidas significativas. ¡Ignacio!"
  },
  CollectionHall_121389_LockTip = {
    Text = "Completa la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121389_Title = {
    Text = "¡Este es mi momento de inversión!"
  },
  CollectionHall_121390_Desc = {
    Text = "Una leyenda completa no puede faltar en convertir enemigos en amigos."
  },
  CollectionHall_121390_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Dificultad · 9-10"
  },
  CollectionHall_121390_Title = {
    Text = "enemigo, amigo"
  },
  CollectionHall_121391_Desc = {
    Text = "De ahora en adelante, te alzas como Guardián entre la multitud de estudiantes y eruditos de Misaq."
  },
  CollectionHall_121391_LockTip = {
    Text = "Completar Operación de investigación · Dificultad 9-11 Desbloqueado"
  },
  CollectionHall_121392_Desc = {
    Text = "Podemos ser momentos fugaces en la eternidad, granos de arena en el torrente.\nSin embargo, el mundo eterno es nuestra preciosa eternidad, porque no importa cuán caótico y loco se vuelva el mundo—\nla dignidad humana se establecerá sobre el brillo de la razón."
  },
  CollectionHall_121392_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación 9-11"
  },
  CollectionHall_121392_Title = {
    Text = "Canto de la eternidad"
  },
  CollectionHall_121393_Desc = {
    Text = "Los héroes se lanzaron de cabeza en los cuentos de hadas, cada cuento de hadas es el mismo, con animales, demonios, hadas y lo desconocido más allá.\n Más allá de la breve libertad y el falso anhelo, al final del cuento de hadas se esconde un corazón falso que le fue impuesto."
  },
  CollectionHall_121393_LockTip = {
    Text = "Completar \"Mundo de Sueños Extraños: Más allá del horizonte · bajo\""
  },
  CollectionHall_121393_Title = {
    Text = "Volando hacia la Vía Láctea"
  },
  CollectionHall_121394_Desc = {
    Text = "Aquí está la Posada de Wanxiang, situada en la fisura espacio-temporal del otro mundo. \n Conectando diferentes universos a través de portales, parpadeando con la vasta luz estelar, dándote la bienvenida. \n Espera... ¿qué estamos haciendo aquí, guardianes del secreto?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Completar la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121394_Title = {
    Text = "¡Bienvenido a la Posada de Wanxiang!"
  },
  CollectionHall_121395_Desc = {
    Text = "La cuchilla de Misaq te asegurará la victoria en este enfrentamiento. \n El vínculo entre tú y tu compañero es inquebrantable. \n Incluso si algún día están en universos diferentes, esto no cambiará."
  },
  CollectionHall_121395_LockTip = {
    Text = "Completar conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121395_Title = {
    Text = "¡La espada de Mythag!"
  },
  CollectionHall_121396_Desc = {
    Text = "«¿No has completado el entrenamiento diario? ¿Qué tal si jugamos una partida de Carta de Cartas Wanxiang primero?»\n«¿No has luchado en la Zona Prohibida de Catástrofe de Fusión? ¿Qué tal si jugamos una partida de Carta de Cartas Wanxiang primero?»\n«¡Esto es Fase de Duelo, no Carta de Cartas Wanxiang! ¡Reuniré mil bellotas para que lo veas!»"
  },
  CollectionHall_121396_LockTip = {
    Text = "Completar la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121396_Title = {
    Text = "¡Juguemos a las cartas de Wanxiang!"
  },
  CollectionHall_121397_Desc = {
    Text = "Llama mi nombre, antes del amanecer olvidado."
  },
  CollectionHall_121397_LockTip = {
    Text = "Completar Operación de investigación · Dificultad 9-11 Desbloqueado"
  },
  CollectionHall_121397_Title = {
    Text = "Venido del olvido@2"
  },
  CollectionHall_121398_Desc = {
    Text = "\"¡Ven y firma un contrato conmigo para convertirte en un Maestro de cartas!\"\nEsta chica dragón de otro mundo te hizo una invitación cálida pero desconcertante.\nPara restaurar rápidamente la normalidad en este pequeño incidente del espacio de fase, no tienes otra opción."
  },
  CollectionHall_121398_LockTip = {
    Text = "Completa la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121398_Title = {
    Text = "¡Posadera, Ignacio!"
  },
  CollectionHall_121399_Desc = {
    Text = "Los que vienen después encontrarán esta nota al pie bajo un pesado regalo. \n El único que escapó de ser un héroe se convirtió en héroe, y el niño que valora a sus amigos solo tiene un único amigo que le queda."
  },
  CollectionHall_121399_LockTip = {
    Text = "Completar el errante \"Día de la coronación\""
  },
  CollectionHall_121399_Title = {
    Text = "Yo andaré solo"
  },
  CollectionHall_121400_Desc = {
    Text = "Aléjate del maestro, enfréntate al maestro, desafía al maestro.\nTu historia es desconocida, pero tu memoria perdurará a través del tiempo."
  },
  CollectionHall_121400_LockTip = {
    Text = "Completar la Operación de investigación 9-13 desbloqueado"
  },
  CollectionHall_121400_Title = {
    Text = "Señor de la locura creadora"
  },
  CollectionHall_121401_Desc = {
    Text = "Nada tiene sentido ahora, por lo tanto, puedes estar aquí. \n Todo lo que fue en el pasado es el significado que tú definiste, por eso estás aquí."
  },
  CollectionHall_121401_LockTip = {
    Text = "Completar la Operación de investigación 9-13 desbloqueado"
  },
  CollectionHall_121401_Title = {
    Text = "Existencialismo"
  },
  CollectionHall_121402_Desc = {
    Text = "El sendero hacia Ellos, el sendero alejado de Ellos. \n Todo está a punto de separarse, todo está a punto de terminar, todo está a punto de comenzar. \n La sombra ante la puerta ha comenzado una larga espera, esperando que la Llave de Plata guíe tu camino de regreso."
  },
  CollectionHall_121402_LockTip = {
    Text = "Completar la Operación de investigación 9-13 desbloqueado"
  },
  CollectionHall_121402_Title = {
    Text = "Sendero hacia Ellos"
  },
  CollectionHall_121403_Desc = {
    Text = "Sus líneas de posibilidades, separándose, convergiendo, colapsando.\nHasta que llegue el único salvador, hasta que finalmente entren en el único final."
  },
  CollectionHall_121403_LockTip = {
    Text = "Completar Operación de investigación · Dificultad 9-10 Desbloqueado"
  },
  CollectionHall_121403_Title = {
    Text = "El único final"
  },
  CollectionHall_121404_Desc = {
    Text = "El joven rey aceptó este trato. \n Dijo, mi reino estará a salvo y en paz."
  },
  CollectionHall_121404_LockTip = {
    Text = "Completar el errante \"Día de la coronación\""
  },
  CollectionHall_121404_Title = {Text = "Coronació"},
  CollectionHall_121405_Desc = {
    Text = "En esta fisura espacio-temporal rota, alguna vez se encontraba la legendaria Posada de Wanxiang. \n Una vez conectaba diferentes universos a través de portales, parpadeando con la vasta luz estelar, dando la bienvenida a cada Maestro de cartas. \n Y tú eres la prueba de que todo esto existió."
  },
  CollectionHall_121405_LockTip = {
    Text = "Completar la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121405_Title = {
    Text = "¡Adiós, Maestro de cartas!"
  },
  CollectionHall_121406_Desc = {
    Text = "El maestro te mira, y tú atravesaste los ojos del maestro."
  },
  CollectionHall_121406_LockTip = {
    Text = "Completar la operación de investigación 9-13 desbloqueado"
  },
  CollectionHall_121406_Title = {
    Text = "Concentración del fin"
  },
  CollectionHall_121407_Desc = {
    Text = "Guerrero, vengador, esclavo, amo, mercader.\n¿Misma postura? ¿Postura diferente? ¿Misma postura."
  },
  CollectionHall_121407_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación 9-11"
  },
  CollectionHall_121407_Title = {
    Text = "Canción de batalla de multiplicidad"
  },
  CollectionHall_121408_Desc = {
    Text = "Sabes que no estás luchando por algo grandioso.\nPara escaparte de las clases, para las tareas, para los postres, para los amigos, para la estufa, para perder el tiempo.\nEres solo una persona común, dispuesta a morir por un día cualquiera."
  },
  CollectionHall_121408_LockTip = {
    Text = "Completar la operación de investigación · Dificultad 9-11 Desbloqueado"
  },
  CollectionHall_121408_Title = {
    Text = "Para los que van a su muerte regularmente"
  },
  CollectionHall_121409_Desc = {
    Text = "Los animales, todos los animales superiores, inevitablemente están controlados por el comportamiento social. \nSin embargo, ella se dirige a la muerte, deseando deconstruir la verdad. \nUna genio loca y sin igual, preferiría provocar la destrucción con sus propias manos, otorgando a todos la salvación de consumir el veneno llamado esperanza."
  },
  CollectionHall_121409_LockTip = {
    Text = "Completar la Operación de investigación 9-13 Desbloqueado"
  },
  CollectionHall_121409_Title = {
    Text = "Deconstrucción del comportamiento comunitario"
  },
  CollectionHall_121410_Desc = {
    Text = "Él envía desde el cielo un flujo incesante de aguas amargas, reuniéndose, reuniéndose. \n Finalmente, se convierte en el río que debe ser recorrido antes de que se fusionen nuestra carne y sangre."
  },
  CollectionHall_121410_LockTip = {
    Text = "Completar \"Mundo de Sueños Extraños: Más allá del horizonte·bajo\""
  },
  CollectionHall_121410_Title = {
    Text = "Río amargo"
  },
  CollectionHall_121411_Desc = {
    Text = "Se despiden con la expectativa de un reencuentro.\nPorque este es un ser querido, y esta es la muerte de un ser querido que no está predeterminada."
  },
  CollectionHall_121411_LockTip = {
    Text = "Completar la Operación de investigación 9-11 Desbloqueado"
  },
  CollectionHall_121411_Title = {
    Text = "La muerte de un ser querido"
  },
  CollectionHall_121412_Desc = {
    Text = [[
Descansa un poco, respira. 
 Incluso si el tema que enfrentas es el fin del mundo, no todos tienen la oportunidad de enfrentarse a tres mentores tan importantes al mismo tiempo.]]
  },
  CollectionHall_121412_LockTip = {
    Text = "Completar la Operación de investigación 9-13 Desbloqueado"
  },
  CollectionHall_121412_Title = {Text = "Interludio"},
  CollectionHall_121413_Desc = {
    Text = "La historia de mil bellotas siempre comienza con la primera. \n En la Fase de Duelo, cada vez que juegas una carta, \n una ráfaga de recuerdos dorados pasa inexplicablemente por los ojos de Ignacio."
  },
  CollectionHall_121413_LockTip = {
    Text = "Completar la conexión multidimensional\"Mi turno\""
  },
  CollectionHall_121413_Title = {
    Text = "¡Recargas ilimitadas!"
  },
  CollectionHall_121414_Desc = {
    Text = "Locura, preludio de la destrucción, esta es la lógica subyacente del mundo ordenado.\n¿Él destruirá? ¿El mundo se destruirá?\nNadie lo sabe.\nPero ante el dios creador, la locura está nutriendo su nuevo nacimiento junto con el mundo."
  },
  CollectionHall_121414_LockTip = {
    Text = "Completar la Operación de investigación 9-11 Desbloqueado"
  },
  CollectionHall_121414_Title = {
    Text = "Locura de Fuga"
  },
  CollectionHall_121415_Desc = {
    Text = "¿Cuál es la cosa más irracional del mundo?\nNo tiene propósito, no está relacionada con el rencor, no puede distinguir entre el bien y el mal.\nSolo desea convertir todo lo que nace en sueños en polvo al despertar."
  },
  CollectionHall_121415_LockTip = {
    Text = "Completar Operación de investigación 9-13 Desbloqueado"
  },
  CollectionHall_121415_Title = {
    Text = "polvo de carne"
  },
  CollectionHall_121416_Desc = {
    Text = "Como ese fragmento único, convertirse en un dios es muy sencillo.\nEntonces, ¿cuál es el precio?"
  },
  CollectionHall_121416_LockTip = {
    Text = "Completar la Operación de investigación 9-13 desbloqueado"
  },
  CollectionHall_121416_Title = {
    Text = "Convertirse en un dios"
  },
  CollectionHall_121417_Desc = {
    Text = "A lo largo de la larga civilización humana, hemos construido muchas cosas. \n Sobre la materia, sobre el espíritu, sobre la existencia, el amor, el humo de la guerra y los conflictos. \n Pero eso es solo un ruido insignificante en el sueño del Creador, y una colección de ficciones que se han dejado de lado."
  },
  CollectionHall_121417_LockTip = {
    Text = "Completar Operación de investigación 9-13 Desbloqueado"
  },
  CollectionHall_121417_Title = {
    Text = "Colección de ficción"
  },
  CollectionHall_121418_Desc = {
    Text = "El guardián del secreto más cobarde en la historia de Misaq murió en una felicidad tremenda."
  },
  CollectionHall_121418_LockTip = {
    Text = "Completar Operación de investigación · Dificultad 9-11 Desbloqueado"
  },
  CollectionHall_121418_Title = {
    Text = "El héroe decidido a huir"
  },
  CollectionHall_121898_LockTip = {
    Text = "Desbloquear al completar la operación de investigación Capítulo de las Estrellas 4-0"
  },
  CollectionHall_121898_Title = {
    Text = "Peregrinación de la ilusión eterna"
  },
  CollectionHall_121901_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación Capítulo de las Estrellas 4-16"
  },
  CollectionHall_121901_Title = {
    Text = "Nacimiento de Dios en siete días"
  },
  CollectionHall_122565_LockTip = {
    Text = "Necesitas completar cualquier fase del evento por tiempo limitado \"Sacrificio de la niebla: el yo perdido\""
  },
  CollectionHall_122565_Title = {
    Text = "El rito de fuego de la bruma: el yo perdido"
  },
  CollectionHall_123756_Title = {
    Text = "Bautismo de Plata y Sangre"
  },
  CollectionHall_124124_Desc = {
    Text = "Tienes la posibilidad de encontrar un segundo rostro de muchas existencias, incluso si es un infante que no debería existir o uno nacido de una deidad defectuosa."
  },
  CollectionHall_124124_LockTip = {
    Text = "Desbloquear al completar Operación Capítulo de las Estrellas 4-16"
  },
  CollectionHall_124124_Title = {Text = "Lado Dos"},
  CollectionHall_124125_Desc = {
    Text = "Oh... así que hay un final aún peor."
  },
  CollectionHall_124125_LockTip = {
    Text = "Desbloquear al completar Operación Capítulo de las Estrellas 4-16"
  },
  CollectionHall_124125_Title = {
    Text = "La muerte de ella, él y lo"
  },
  CollectionHall_124126_Desc = {
    Text = "¿Cómo describirías a un compañero que se va cuando es demasiado radiante?\nNo describas su esplendor; describe sus brazos y el aroma a cedro que sientes en él."
  },
  CollectionHall_124126_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación Capítulo de las Estrellas 4-16"
  },
  CollectionHall_124126_Title = {Text = "Cedro"},
  CollectionHall_124127_Desc = {
    Text = "Al final del viaje, sabes quién te está esperando. \n Pero aún no has escapado; caes del cielo de nuevo."
  },
  CollectionHall_124127_LockTip = {
    Text = "Desbloquear al completar Operación de Investigación · Difícil · Capítulo de las Estrellas 4-10"
  },
  CollectionHall_124127_Title = {Text = "Caer"},
  CollectionHall_124128_Desc = {
    Text = "Los niños no pertenecen a la madre; Él ha decidido que todos deben quedarse aquí. \nPermanecer en su dulce paraíso eterno."
  },
  CollectionHall_124128_LockTip = {
    Text = "Desbloquear al completar Operación de Investigación · Dificultad · Capítulo de las Estrellas 4-10"
  },
  CollectionHall_124128_Title = {
    Text = "Paraíso Dulce"
  },
  CollectionHall_124129_Desc = {
    Text = "No tuviste tiempo para salvarla; ella no escapó. \n Fue devorada, dejada indefensa y aislada, y se ató un falso cordón umbilical."
  },
  CollectionHall_124129_LockTip = {
    Text = "Desbloquear al completar Operación de investigación Capítulo de las Estrellas 4-16"
  },
  CollectionHall_124129_Title = {
    Text = "falso cordón umbilical"
  },
  CollectionHall_124130_Desc = {
    Text = "3.14159@2, 3.141592@3, 3.14159265@4...\nUn círculo interminable en la nieve, un pi cruel y que nunca termina."
  },
  CollectionHall_124130_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Dificultad · Capítulo de las Estrellas 4-10"
  },
  CollectionHall_124130_Title = {
    Text = "\"3.14159@4\""
  },
  CollectionHall_124131_Desc = {
    Text = "Llegas tarde otra vez, no te quedes, date prisa, aún más rápido. \n Corre hacia el próximo desenlace."
  },
  CollectionHall_124131_LockTip = {
    Text = "Desbloquear al completar la Operación de investigación Capítulo de las Estrellas 4-16"
  },
  CollectionHall_124131_Title = {
    Text = "Un cierto final"
  },
  CollectionHall_124132_Desc = {
    Text = "Abrázame, mi querido bebé, mi... padre, mi destino."
  },
  CollectionHall_124132_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Difícil · Cápítulo de las Estrellas 4-10"
  },
  CollectionHall_124132_Title = {
    Text = "En el oscuro útero de su hija"
  },
  CollectionHall_124133_Desc = {
    Text = "El cielo está a punto de aclararse, digamos adiós a ayer.\nAdiós al dolor, la absurdidad y la confusión de ayer,\ny demos la bienvenida a un mañana más brillante, cada uno por su camino."
  },
  CollectionHall_124133_LockTip = {
    Text = "Desbloquear al completar Operación de Investigación · Difícil · Capítulo de las Estrellas 4-10"
  },
  CollectionHall_124133_Title = {
