  CollectionHall_133770_Desc = {
    Text = "¡Saludos, pasajeros!\n¡El Festival de Oración por el Año se acerca! En esta alegre temporada de reencuentros y nuevos comienzos, toda nuestra tripulación extiende los más sinceros deseos a todos ustedes, viajeros cansados que emprenden el largo camino a casa:\n\n¡Les deseamos un feliz Festival de Oración por el Año, alegres reuniones familiares, un viaje veloz y lo mejor de todo! <(￣︶￣)↗[GO!]"
  },
