  CollectionHall_147988_Desc = {
    Text = "Guarda tu tediosa corona; jamás le dediqué una segunda mirada. ¡Desenvaina tu hoja —el mundo enloquece por la sangre! \n¡Por esto, y solo por esto— \n¡Mata! ¡Devora! ¡Perece!"
