  CollectionHall_48635_Desc = {
    Text = "<Title:Profile>\nDecana interina de Mythag.\nAprendiz de Crowley McKinnon, un junior directo de Herbert.\nUna de las testigos del asesinato de su mentor por parte de Herbert, ha gestionado los asuntos de la academia desde la muerte del mentor.\nUna fanática absoluta de la eficiencia, nunca llega tarde y mantiene su cabello corto para ahorrar tiempo en el arreglo.\nHuyó de su tierra natal devastada por la guerra, Elche, hacia Leo.\nSu dedo índice derecho no puede doblarse correctamente, supuestamente debido a un trato brutal en un campo de concentración."
  },
