  CollectionHall_48635_Title = {Text = "Czort"},
  CollectionHall_48636_Desc = {
    Text = "<Title:Introducción>\nUno de los tres fundadores, junto a Ward Phillips y Kralarques, estableció el predecedor de la Universidad de Mitag—el Colegio Mitag.\nElla es la primera \"Despertadora\" y la fuente de la tecnología de Despertadores.\nGuardando el Pozo Negro durante muchos años, muy pocas personas han visto su rostro, convirtiéndola en uno de los más altos secretos de la Universidad de Mitag.\n\"Shh... no indagues tu @2.\""
  },
