  CollectionHall_71008_Title = {
    Text = "El viaje continúa entre el polvo"
  },
  CollectionHall_71009_Desc = {
    Text = "El mensajero con seis alas de plata desciende al Pozo Negro a través de la Puerta de la Existencia, trayendo guía primordial y el mensaje de la verdad."
  },
  CollectionHall_71009_Title = {
    Text = "Cruza la puerta y llega"
  },
  CollectionHall_71010_Desc = {
    Text = "Invasores de otro mundo, esparciendo muerte y sombra en el mundo despierto con el triángulo invertido."
  },
  CollectionHall_71010_Title = {
    Text = "Sonata de la Crisis"
  },
  CollectionHall_71011_Desc = {
