  },
  CollectionHall_71012_Desc = {
    Text = "El principio de supervivencia, la esperanza de supervivencia, radica en un destello de la Llave de Plata.\nEn este momento, el heredero inscribe una tableta de piedra, y el buscador hace un voto aquí."
  },
  CollectionHall_71012_Title = {
