  },
  CollectionHall_71015_Desc = {
    Text = "Los pioneros abrieron el camino, y los sucesores continúan la búsqueda. La luz del medidor de núcleo de plata nunca se desvanece, y la investigación de los habitantes de Missaga tampoco cesará."
