  CollectionHall_71027_Desc = {
    Text = "La verdad se oculta tras la puerta, solo se puede vislumbrar su rostro velado durante el instante en que \"Él\" respira.\nA.F.315  Número de llave plateada K-0617  La primera apertura de la puerta plateada"
