  CollectionHall_71028_Desc = {
    Text = "Las reglas del museo de cera son tres: primero, no tocar las figuras de cera; segundo, no destapar las figuras de cera; tercero, no derramar sangre en el museo de cera. Bajo ningún concepto debes violar estas reglas."
