  },
  CollectionHall_89347_Desc = {
    Text = "Las personas se matan entre sí apresuradas, con la ilusión de que así podrán purificar sus pecados y ser las primeras en pisar el puro y sin mancha Reino de Dios."
  },
  CollectionHall_89347_LockTip = {
