  },
  CollectionHall_89347_Title = {Text = "Delirio"},
  CollectionHall_89348_Desc = {
    Text = "¡Hermoso! ¡Abundante! ¡La patria ideal, Lemuria!\n¡Poderoso! ¡Resistente! ¡Bajo la protección del Rey Divino, Lemuria!\n¡Genial! ¡Genial! ¡El país eterno, Lemuria!"
  },
