  },
  CollectionHall_89348_Title = {
    Text = "Tierra Real Eterna"
  },
  CollectionHall_89349_Desc = {
    Text = "El abandono y la traición son comunes entre los de alta jerarquía; no expongas tu espalda a ellos para evitar convertirte en la última luz y calor."
  },
  CollectionHall_89349_LockTip = {
    Text = "Completar \"Operación de investigación\" · Difícil 3-10 Desbloqueado"
  },
  CollectionHall_89349_Title = {Text = "Abandonado"},
  CollectionHall_89350_Desc = {
    Text = "Su Alma está detrás de ti, y tú solo eres la única pared en este momento, mientras la impotencia del destino te captura firmemente; no puedes cambiar ese final.\nEl final donde ella es sumergida por la marea negra."
  },
  CollectionHall_89350_LockTip = {
