  },
  CollectionHall_89350_Title = {
    Text = "Rescate en soledad"
  },
  CollectionHall_89351_Desc = {
    Text = "Oíste a alguien susurrar suavemente en tu oído, los susurros sonando entre labios y dientes.\nPrestaste atención, intentando discernir esas vagas palabras, hasta que el mismo sonido susurrante resonó en tu cráneo, y te diste cuenta de que era el sonido de innumerables alas de insectos resonando juntas—susurro, susurrando, ve a casa, ve a casa."
  },
  CollectionHall_89351_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 2-18"
  },
  CollectionHall_89351_Title = {
    Text = "Murmullo de insectos infinitos"
  },
  CollectionHall_89352_Desc = {
    Text = "En los momentos cruciales de la vida, siempre parece que hay una fina llovizna acompañando. \nDespedirse de esos recuerdos en medio de la fina lluvia, enterrando el vino amargo en tu corazón, sostén la Llave de plata en tu mano y comienza un nuevo viaje. \nQue la Llave de plata nos guíe."
  },
  CollectionHall_89352_LockTip = {
