  },
  CollectionHall_89352_Title = {
    Text = "Adiós, Feifei"
  },
  CollectionHall_89353_Desc = {
    Text = "El cálido sol de primavera, el palacio de ensueño, los vestidos que giran, el baile lleno de risas, y la hermosa y gentil princesa.  \nEstos son todo lo que los caballeros desean proteger."
  },
  CollectionHall_89353_LockTip = {
    Text = "Completa \"Deseo del Caballero\" en The Wandering"
  },
  CollectionHall_89353_Title = {
    Text = "Fiesta de primavera en el palacio"
  },
  CollectionHall_89354_Desc = {
    Text = "Sangre, matanza, cambio... enterrada bajo la interminable arena amarilla se encuentra una historia cruel y común dentro del río del tiempo."
  },
  CollectionHall_89354_LockTip = {
    Text = "Completa \"Descendencia Pálida\" en dificultad Difícil en El Errante"
  },
  CollectionHall_89354_Title = {
