  CollectionHall_89363_Title = {
    Text = "Gloria merecida"
  },
  CollectionHall_89364_Desc = {
    Text = "¿A dónde llevará este barco en su largo viaje?  \nLa diosa pura y blanca canta sentada en lo alto del mástil.  \nCodicia, locura, lucha y traición, ella lo ignora todo.  \nNo canta sobre el destino cambiante, solo canta  \nel regreso del viejo capitán"
