  CollectionHall_89367_Desc = {
    Text = "Las mareas suben, los gritos resuenan, los recuerdos dolorosos surgen, desgarrando el espíritu de la chica. Las lágrimas negras que fluyen de sus ojos son sus silenciosos gritos de ayuda."
