  CollectionHall_89370_Title = {
    Text = "Lápida pegajosa"
  },
  CollectionHall_89371_Desc = {
    Text = "Fragancia elegante, un sinfín de bienes, pero ¿cuántos pueden permitirse el precio establecido por la Señora Narciso?"
