  CollectionHall_89372_LockTip = {
    Text = "Desbloquear Investigación Operación 3-14"
  },
  CollectionHall_89372_Title = {
    Text = "No te preocupes, estoy contigo"
  },
  CollectionHall_89373_Desc = {
    Text = "El tiempo está aullando, el tiempo está rugiendo, el tiempo está persiguiendo a aquellos que han fallado tres veces. No trates de huir, pues el desenlace ya está predeterminado."
  },
  CollectionHall_89373_LockTip = {
    Text = "Desbloquear al completar \"Operación\" 4-12 · Difícil"
  },
  CollectionHall_89373_Title = {
    Text = "Monstruo de causalidad"
  },
  CollectionHall_89374_Desc = {
    Text = "El juicio no se detendrá; el juicio debe ser ejecutado.\nLos monstruos nacen del espejo, con su propia carne y sangre como mecha, propagando el fuego de la purificación por todo el mundo."
  },
  CollectionHall_89374_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\" en dificultad Difícil"
  },
  CollectionHall_89374_Title = {
    Text = "Luz de carne"
  },
  CollectionHall_89375_Desc = {
    Text = "Cuando las posiciones y voluntades colisionan, los humanos a menudo solo creen en sus propios principios.\nPara la mayoría de la gente, lo que creen es la única justicia."
  },
  CollectionHall_89375_LockTip = {
    Text = "Desbloquear Investigación Operación 4-16"
  },
  CollectionHall_89375_Title = {
    Text = "Justicia contraria"
  },
  CollectionHall_89376_Desc = {
    Text = "La reunión llegó demasiado temprano, la verdad llegó demasiado tarde, el alma destrozada por la cruel realidad se está sanando gradualmente en sus pequeñas manos. \nLos dos persiguiéndose a través del viento y la nieve finalmente se abrazan y lloran en la hendidura que trasciende el tiempo."
  },
  CollectionHall_89376_LockTip = {
    Text = "Desbloquear Investigación Operación 4-16"
  },
  CollectionHall_89376_Title = {
    Text = "Reencuentro inesperado"
  },
  CollectionHall_89377_Desc = {
    Text = "Como dama, ¡uno siempre debe mantener la elegancia! \nPor supuesto, quiero decir, ¡lo que sea que haga una dama es elegante!"
  },
  CollectionHall_89377_LockTip = {
    Text = "Desbloquear Investigación Operación 5-15"
  },
  CollectionHall_89377_Title = {
    Text = "Dama del Mar Profundo"
  },
  CollectionHall_89378_Desc = {
    Text = "La cálida hoguera da la bienvenida a cada huésped. Pero ten cuidado, la noche tiene perros feroces; no salgas afuera."
  },
  CollectionHall_89378_LockTip = {
    Text = "Desbloquear Investigación Operación 3-14"
  },
  CollectionHall_89378_Title = {
    Text = "Pueblo en la noche de nieve"
  },
  CollectionHall_89379_Desc = {
    Text = "Detrás de esta puerta, que puede incluso aprisionar el tiempo, está la elección final de una madre para proteger a su amada hija. \n\"Te amo, Lily.\""
  },
  CollectionHall_89379_LockTip = {
    Text = "Completar \"Operación de investigación\" · Difícil 4-12 para desbloquear"
  },
  CollectionHall_89379_Title = {
    Text = "Prisión eterna"
  },
  CollectionHall_89380_Desc = {
