  CollectionHall_89381_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\""
  },
  CollectionHall_89381_Title = {
    Text = "Santo ciego"
  },
  CollectionHall_89382_Desc = {
    Text = "En ese momento, madre pasó las páginas, contando cuentos de hadas a su hijo.\nEl calor de la tarde fluía a través de este espacio estrecho a lo largo del tiempo."
  },
  CollectionHall_89382_LockTip = {
    Text = "Desbloquear Investigación Operación 4-16"
  },
  CollectionHall_89382_Title = {
    Text = "Cuento de la Tarde"
  },
  CollectionHall_89383_Desc = {
    Text = "¿Cómo puedo engañarme a mí mismo para fantasear que la vida aún continúa entre las brasas apagadas? \nElla duerme dentro de un oscuro capullo y un viscoso rojo, mirando el distante cielo estrellado en un sueño.\n\"Eso es demasiado frío, pero ¿dónde está el calor que una vez tuve?\""
  },
  CollectionHall_89383_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 2-18"
  },
  CollectionHall_89383_Title = {
    Text = "Delirio de Cenizas"
  },
  CollectionHall_89384_Desc = {
    Text = "¡Canta en voz alta, canta en voz alta!\n¡Deja que la maquinaria derretida resuene por todo el universo, alabando el fin llamado Oscuridad Eterna!"
  },
  CollectionHall_89384_LockTip = {
    Text = "Completar \"Operación de Investigación\" · Difícil \"Historia Estelar\" 1-10 para desbloquear"
  },
  CollectionHall_89384_Title = {
    Text = "Cantata del Final de Fusión"
  },
  CollectionHall_89385_Desc = {
    Text = "Sangre y carne vuelan, hojas afiladas danzan salvajemente, monstruos cantan fuertemente en palabras incomprensibles. El único pensamiento que queda en el cerebro enloquecido es—captúrala, a cualquier precio, captúrala."
  },
  CollectionHall_89385_LockTip = {
    Text = "Completar \"Operación de investigación\" · Difícil 3-10 para desbloquear"
  },
  CollectionHall_89385_Title = {
    Text = "Locura de la fijación"
  },
  CollectionHall_89386_Desc = {
    Text = "Mira, la Luna Carmesí ha salido, y todos los pecadores serán purificados."
  },
  CollectionHall_89386_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\""
  },
  CollectionHall_89386_Title = {
    Text = "Luna de Sangre"
  },
  CollectionHall_89387_Desc = {
    Text = "Padre misericordioso, quemaré mi carne ósea, incineraré mi alma, para servir de leña para \"la llama pálida\". \nPor favor, coloca todo el sufrimiento sobre mí, para que esos niños perdidos puedan continuar su camino."
  },
  CollectionHall_89387_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\" en dificultad Difícil"
  },
  CollectionHall_89387_Title = {
    Text = "Gracia Divina"
  },
  CollectionHall_89388_Desc = {
    Text = "La Linterna expulsará todo mal.\nDebes arrepentirte devotamente, derramar cada gota de sangre, para limpiar los pecados y ascender al cielo."
  },
  CollectionHall_89388_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\""
  },
  CollectionHall_89388_Title = {
    Text = "Que la linterna brille siempre"
  },
  CollectionHall_89389_Desc = {
    Text = "Me prometiste, todos me prometieron. \nSi no puedo salvar a Lemuria, ¡entonces vayamos juntos y seamos enterrados con ella!"
  },
  CollectionHall_89389_LockTip = {
    Text = "Desbloquear al completar Operación de Investigación · Difícil 5-10"
  },
  CollectionHall_89389_Title = {
    Text = "Juicio de delirio"
