  },
  CollectionHall_89390_Title = {
    Text = "Sin arrepentimiento"
  },
  CollectionHall_89391_Desc = {
    Text = "Las notas que colapsan bailan, y la realidad desmoronada ruge.\nNi siquiera los tentáculos del sueño alcanzan este lugar."
  },
  CollectionHall_89391_LockTip = {
