  CollectionHall_89392_Desc = {
    Text = "La dama del Abismo está decidida a llevar a cabo su voluntad y perseguir la libertad inalcanzable."
  },
  CollectionHall_89392_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Difícil 5-10"
  },
  CollectionHall_89392_Title = {
    Text = "Determinación bajo la marea"
  },
  CollectionHall_89393_Desc = {
    Text = "Te llevaré de regreso, de regreso para conocer al \"maestro,\" solo así..."
  },
  CollectionHall_89393_LockTip = {
    Text = "Desbloquear Investigación Operación 3-14"
  },
  CollectionHall_89393_Title = {
    Text = "Origen común de la carne"
  },
  CollectionHall_89394_Desc = {
    Text = "Lo que estás enfrentando son innumerables almas afines. Ellos te resisten, te invitan, suelta tu yo sin sentido, y deja que tu cerebro ignorante se una al colectivo nunca solitario."
  },
  CollectionHall_89394_LockTip = {
    Text = "Completar \"Operación de Investigación\" · Difícil \"Historia Estelar\" 2-12 para desbloquear"
