  },
  CollectionHall_89395_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\""
  },
  CollectionHall_89395_Title = {
    Text = "Bondad desinteresada"
  },
  CollectionHall_89396_Desc = {
    Text = "Toma mi mano, y lleva esa flor eternamente vívida de la memoria.\nNo mires atrás, porque seguramente llegaremos a esa brillante Puerta plateada."
  },
