  },
  CollectionHall_89398_Title = {
    Text = "Sol Negro Totém"
  },
  CollectionHall_89399_Desc = {
    Text = "Una niebla gris envuelve el sol negro, el polvo llena la boca y la nariz.\nNo respires por la boca—la esperanza ha sido enterrada antes de esto."
  },
  CollectionHall_89399_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 1-14"
  },
  CollectionHall_89399_Title = {
    Text = "Polvo asfixiante"
  },
  CollectionHall_89400_Desc = {
    Text = "Abre tu cavidad craneal y resuena con los innumerables cráneos.\nLa respuesta puede estar oculta dentro."
  },
  CollectionHall_89400_LockTip = {
    Text = "Completar Operación de Investigación · Difícil Historia Estelar 1-10 para desbloquear"
  },
  CollectionHall_89400_Title = {
    Text = "Resonancia de la cavidad craneal"
  },
  CollectionHall_89401_Desc = {
    Text = "Invierno, bruja, niños, una nieve que nunca cesa."
  },
  CollectionHall_89401_LockTip = {
    Text = "Desbloquear Investigación Operación 3-14"
  },
  CollectionHall_89401_Title = {
    Text = "Ciudad de la Sombra Devoradora bajo la Nieve"
  },
  CollectionHall_89402_Desc = {
    Text = "Susurros extraños reverberan en el aire, mientras el limo negro devora las ofrendas, esperando el regreso del Dios de tiempos antiguos."
  },
  CollectionHall_89402_LockTip = {
    Text = "Desbloquear Investigación Operación 4-16"
  },
  CollectionHall_89402_Title = {
    Text = "Altar Polar"
  },
  CollectionHall_89403_Desc = {
    Text = "La luz disipó la oscuridad, brillando igualmente sobre cada niño.\nEra pálida y débil, pero increíblemente cálida, llena de poder.\nQue esta tenue luz borre tu sufrimiento y calme tu corazón, mi niño."
  },
  CollectionHall_89403_LockTip = {
    Text = "Completa el registro especial \"Color de Sangre\" en dificultad Difícil"
  },
  CollectionHall_89403_Title = {
    Text = "Llama pálida sanadora"
  },
  CollectionHall_89404_Desc = {
    Text = "El tren se detuvo de repente, y los gemelos llegaron siguiendo el olor de la línea de sangre."
  },
  CollectionHall_89404_LockTip = {
    Text = "Desbloquear Investigación Operación 3-14"
  },
  CollectionHall_89404_Title = {
    Text = "frenazo brusco"
  },
  CollectionHall_89405_Desc = {
    Text = "O Rey, he seguido la profecía y esperado diez mil años, ¿por qué el futuro sigue tan lejos?\nDebo continuar orando, pero perdóname, ya no puedo esperar."
  },
  CollectionHall_89405_LockTip = {
    Text = "Desbloquear Investigación Operación 5-15"
  },
  CollectionHall_89405_Title = {
    Text = "Oración de mil millones"
  },
  CollectionHall_89406_Desc = {
    Text = "El bajo ladrón robó el poder del rey, intentando obstruir el gran ritual.\n¡El irrespetuoso falso debe pagar con la muerte!"
  },
  CollectionHall_89406_LockTip = {
    Text = "Desbloquear al completar Operación de investigación · Difícil 5-10"
  },
  CollectionHall_89406_Title = {
    Text = "Juramento de blasfemia"
  },
  CollectionHall_89407_Desc = {
    Text = "En esa densa niebla, donde el sol no es visible, caminaré solo hacia lo desconocido que tengo adelante.\nReuniré polvo, sangre y fuego de esa niebla, calmando esas lágrimas solitarias, confundidas y tristes.\nYa no temeré, pues el sol eterno ha estado elevado en mi corazón."
  },
  CollectionHall_89407_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 2-18"
  },
  CollectionHall_89407_Title = {Text = "Iré hasta"},
  CollectionHall_89408_Desc = {
    Text = "A todos los niños se les ha dicho: no mires directamente al sol con tus ojos humanos.\nIncluso en este momento, Él ya ha caído."
  },
  CollectionHall_89408_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 1-14"
  },
  CollectionHall_89408_Title = {
    Text = "Renacer del Día del Sol Negro"
  },
  CollectionHall_89409_Desc = {
    Text = "Bienvenido al sanatorio neurológico privado de la doctora Clementine. Sigue las indicaciones de la doctora, libera todo el dolor de tu mente y avanza hacia la curación definitiva."
  },
  CollectionHall_89409_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 2-18"
  },
  CollectionHall_89409_Title = {
    Text = "Sueño de la colonia alucinógena"
  },
  CollectionHall_89410_Desc = {
    Text = "La gloria del pasado ya ha pasado, dejando solo las ruinas en la memoria."
  },
  CollectionHall_89410_LockTip = {
    Text = "Completa \"Descendencia Pálida\" en El Errante"
  },
  CollectionHall_89410_Title = {
    Text = "Resplandor del pasado"
  },
  CollectionHall_89411_Desc = {
    Text = "Te hundiste en el Abismo, y de tu bolsillo salió su último mensaje. Así, en la interminable oscuridad, vislumbraste un momento de luz."
  },
  CollectionHall_89411_LockTip = {
    Text = "Completar \"Operación de investigación\" · Difícil Historia Estelar 2-12 para desbloquear"
  },
  CollectionHall_89411_Title = {
    Text = "Crisálida Break"
  },
  CollectionHall_89412_Desc = {
    Text = "Lo que estaba una vez delante de ti ahora está detrás de ti. \nSiempre has creído que después de correr con todas tus fuerzas, esperando al final de ese tiempo y espacio, sin duda estarán esas manos familiares y cálidas."
  },
  CollectionHall_89412_LockTip = {
    Text = "Completar \"Operación de Investigación\" · Difícil Historia Estelar 2-12 para desbloquear"
  },
  CollectionHall_89412_Title = {
    Text = "Decisión inmutable"
  },
  CollectionHall_89413_Desc = {
    Text = "Aunque el ataque en el metro es desafortunado, es justo adecuado como un espectáculo posterior para satisfacer la curiosidad de la chica."
  },
  CollectionHall_89413_LockTip = {
    Text = "Desbloquear Investigación Operación 3-14"
  },
  CollectionHall_89413_Title = {
    Text = "Aventura en el Túnel"
  },
  CollectionHall_89414_Desc = {
    Text = "Los héroes y la princesa corren bajo el cielo nocturno, la grava bajo sus pies cuenta la alegría de la vida. Ese corazón, sellado durante mil años, comienza a latir lentamente con el paso de una estrella fugaz."
  },
  CollectionHall_89414_LockTip = {
    Text = "Completa \"Descendencia Pálida\" en dificultad Difícil en El Errante"
  },
  CollectionHall_89414_Title = {
    Text = "La estrella fugaz de ambos"
  },
  CollectionHall_89415_Desc = {
    Text = "No hay necesidad de palabras, cuando vengas aquí, recibirás la ayuda más sincera. \nLa guía sonriente ha extendido su mano hacia ti; ella te llevará a lo profundo del bosque de tu alma que nunca has visto claramente."
  },
  CollectionHall_89415_LockTip = {
    Text = "Desbloquear Investigación Operación Capítulo Estrella 2-18"
  },
  CollectionHall_89415_Title = {
    Text = "Bosque de la Mente"
  },
  CollectionHall_89416_Desc = {
    Text = "Cuando el primer rayo de sol matutino del valle iluminó el laberinto, la princesa que había dormido mil años con mil pies y mil hijos recibió a su último fiel seguidor."
  },
  CollectionHall_89416_LockTip = {
    Text = "Completa \"Descendencia Pálida\" en El Errante"
  },
  CollectionHall_89416_Title = {
    Text = "Amanecer en Cambrian"
  },
  CollectionHall_89417_Desc = {
    Text = "El proceso de pensamiento de un genio siempre es algo sinuoso, intrincado y diferente, pero eso es precisamente lo que la hace adorable, ¿no es así?"
  },
  CollectionHall_89417_LockTip = {
    Text = "Completa \"Núcleo Torcido\" en el vagar"
  },
  CollectionHall_89417_Title = {
    Text = "Los problemas de un genio"
  },
  CollectionHall_89418_Desc = {
    Text = "Ven a jugar un juego conmigo, no te preocupes, no es tan peligroso, solo para pasar el aburrido tiempo."
  },
  CollectionHall_89418_LockTip = {
    Text = "Completa \"Descendencia Pálida\" en El Errante"
  },
  CollectionHall_89418_Title = {
    Text = "juego de adivinanzas"
  },
  CollectionHall_89419_Desc = {
    Text = "La marea fantasmal, tejida en una cortina bajo la atracción celestial, es pisoteada por los seres extraños que caminan sobre las olas."
  },
  CollectionHall_89419_LockTip = {
    Text = "Desbloquear Investigación Operación 5-15"
  },
  CollectionHall_89419_Title = {
    Text = "Marea Ilusoria"
  },
  CollectionHall_89420_Desc = {
    Text = "El rey es supremo, la autoridad del rey es ilimitada, el rey se sienta majestuoso en su esplendor, solitario mirando su reino."
  },
  CollectionHall_89420_LockTip = {
    Text = "Desbloquear Investigación Operación 5-15"
  },
  CollectionHall_89420_Title = {
    Text = "Rey durmiente del abismo"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:简介>\nHuérfana, de origen desconocido, desde que tiene memoria fue adoptada por la tripulación y vivió a bordo de un barco.\nDebido a esta experiencia, desde niña Kepsante ha sentido un profundo anhelo y curiosidad por el océano.\nCuando creció, naturalmente eligió una profesión relacionada con el mar y los barcos: navegante.\nDesde entonces, la joven apasionada del océano ha estado eternamente vagando sobre las aguas, guiando la dirección de los barcos bajo el resplandor de las estrellas.\nElla \"nació\" en el mar, en el barco.\nY tampoco teme \"morir\" en el mar, en el barco.\nAsí es como vive."
  },
  CollectionHall_89706_LockTip = {
    Text = "Desbloqueado tras despertar a\"Cuphantes\""
  },
  CollectionHall_89706_Title = {Text = "Corposant"},
  CollectionHall_89968_Desc = {
    Text = "Sangre, odio, locura y dolor; el campo de batalla nunca carece de estos. Cuando apuestas tu vida en la mesa de póker del monstruo, deberías pensar en qué tipo de vórtice carmesí causará."
  },
  CollectionHall_89968_LockTip = {
    Text = "Completa \"Sangre y Arena\" en La Errante"
  },
  CollectionHall_89968_Title = {
    Text = "Remolino Escarlata"
  },
  CollectionHall_89969_Desc = {
    Text = "Según la leyenda, el navegante se transformará en un destello azul y blanco sobre el mástil después de la muerte, continuando para guiar el viaje del barco.\nCuando ella encendió su vida en la cima del mástil, ¿vio el camino de la esperanza regresar?"
  },
  CollectionHall_89969_LockTip = {
    Text = "Completa la vagabundeo de conciencia \"La Última Navegación\""
  },
  CollectionHall_89969_Title = {
    Text = "Fuego de San Elmo"
  },
  CollectionHall_89970_Desc = {
    Text = "Ella nació con un destino lleno de odio, violencia y luchas interminables. \n Cuando abandonó todas las ilusiones suaves y cálidas y eligió tomar cuchillos y armas, la canción triunfal del destino ya había comenzado a sonar para ella. \n Estaba destinada a convertirse en una guerrera, lavando su odio con la sangre de sus enemigos, y luego vivir una vida que quizás no sea gloriosa, pero sí valiente y sin remordimientos."
  },
  CollectionHall_89970_LockTip = {
    Text = "Completa el registro especial \"Regresador de Elworth\""
  },
  CollectionHall_89970_Title = {
    Text = "Sangre para limpiar agravios"
  },
  CollectionHall_89971_Desc = {
    Text = "Debajo del sol poniente de color rojo sangre yace arena amarilla empapada en sangre.\nEl guerrero más fuerte se encuentra en el campo de batalla a punto de hundirse en la noche, recordando las llamas doradas y la gloria de antaño.\nIncontables buitres gritando se elevan, bloqueando los últimos rayos de luz del sol. En la gran expedición oriental, el desierto está lleno de no-muertos, acompañándolo en su entierro."
  },
  CollectionHall_89971_LockTip = {
    Text = "Completa \"Sangre y Arena\" en dificultad Difícil en El Errante"
  },
  CollectionHall_89971_Title = {
    Text = "Sol rojo bañado en sangre"
  },
  CollectionHall_89972_Desc = {
    Text = "Si este mundo ha caído en la oscuridad, entonces seré la última antorcha.\nSi ya no hay justicia entre la multitud, entonces hablaré por los más débiles."
  },
  CollectionHall_89972_LockTip = {
    Text = "Completa la vagabundeo de conciencia \"La Última Navegación\""
  },
  CollectionHall_89972_Title = {
    Text = "Llama de la Noche Larga"
  },
  CollectionHall_89973_Desc = {
    Text = "Esa fue su batalla destinada, el campo de batalla al que debe llegar.\nElla desechó toda debilidad, vacilación y miedo para abrazar el pasado.\nNo tiene arrepentimientos, pues ha comprendido el verdadero significado de luchar en esta vida.\nNo está sola; la espada en su mano refleja el feroz rostro de otro yo."
  },
  CollectionHall_89973_LockTip = {
    Text = "Completa el registro especial \"Regresador de Elworth\" en dificultad Difícil"
  },
  CollectionHall_89973_Title = {
    Text = "Preguntar a las montañas"
  },
  CollectionHall_89974_Desc = {
    Text = "Hey ho, hey ho, levanta el ancla, izar las velas, desata la última cuerda.\nNuestro navegante ha subido al palo, y la bandera colorida ondea alto.\n¡Set de vela, set de vela, en la dirección que ella apunta, zarparemos!"
  },
  CollectionHall_89974_LockTip = {
    Text = "Completa la vagabundeo de conciencia \"La Última Navegación\""
  },
  CollectionHall_89974_Title = {
    Text = "Diario del navegante"
  },
  CollectionHall_89975_Desc = {
    Text = "Cada vez que ella zarpa, está preparada con la última voluntad.\nLa canción que ha sido transmitida a través de generaciones actúa como una canción de cuna en un sueño, abrazando suavemente su alma.\nLas brillantes banderas ondean al viento; su carne puede desmoronarse, pudrirse o hundirse en el profundo mar, pero su alma seguramente se mantendrá sobre su barco, enviando luz eterna hacia las estrellas y el mar."
  },
  CollectionHall_89975_LockTip = {
    Text = "Completa la vagabundeo de conciencia \"La Última Navegación\""
  },
  CollectionHall_89975_Title = {
    Text = "Lamento del Navegante"
  },
  CollectionHall_89976_Desc = {
    Text = "En el desierto de Kusi, la tormenta de arena es una invitada constante; la arena que vuela por los aires entra en la boca y la nariz de los vivos, y también cubre los cuerpos sin nombre de los muertos. \n Solo las bestias sedientas de carne y sangre husmean atentamente en el viento, buscando el aroma dulce de un festín."
  },
  CollectionHall_89976_LockTip = {
    Text = "Completa \"Sangre y Arena\" en La Errante"
  },
  CollectionHall_89976_Title = {
    Text = "Arena y bestias"
  },
  CollectionHall_89977_Desc = {
    Text = "El sol en el desierto no es como en otros lugares; es pálido, deslumbrante y cruel, jamás muestra un lado cálido. La bestia no puede imaginar la primavera que describes, así que por favor, ve tú por ella y contempla ese sol verdadero del que hablas."
  },
  CollectionHall_89977_LockTip = {
    Text = "Completa \"Sangre y Arena\" en La Errante"
  },
  CollectionHall_89977_Title = {
    Text = "Sangre y arena sin retorno"
  },
  CollectionHall_89978_Desc = {
    Text = "La nieve interminable cae, danzando en el aire, cubriendo el cabello de los guerreros con escarcha.\nEn este momento, los recuerdos de su vida fluyen; ella camina desde las sutiles profundidades de los corazones humanos, dirigiéndose hacia las montañas imponentes.\nTraición, abandono y protección, todo el dolor y la ira son meramente una serie de batallas. Con las personas, con las montañas, y consigo misma.\nElla mira a su líder, a los nuevos compañeros, desconocidos pero familiares, revelando una sonrisa incómoda.\nUn día puede que triunfe, o puede caer para siempre en el campo de batalla, pero incluso en el momento de ascender al cielo o descender al infierno, no dejará caer la espada en su mano.\nPara evitar perderlo todo de nuevo, esta vez elige levantar la espada de protección antes de buscar venganza, dirigiéndose sola a su campo de batalla."
  },
  CollectionHall_89978_LockTip = {
    Text = "Completa el registro especial \"Regresador de Elworth\""
  },
  CollectionHall_89978_Title = {
    Text = "Para un mañana sin nuevas pérdidas"
  },
  CollectionHall_89998_LockTip = {
    Text = "Necesitas completar cualquier etapa del evento por tiempo limitado «Sombra que observa el Reino de Dios: Marea Anómala»"
  },
  CollectionHall_89998_Title = {
    Text = "Sombra que observa el Reino de Dios: Marea Anómala"
  },
  CollectionHall_89999_LockTip = {
    Text = "Necesitas completar cualquier etapa del evento por tiempo limitado \"Prisionero del espejo: Vuelo bajo el cielo azul\""
  },
  CollectionHall_89999_Title = {
    Text = "Prisionero del espejo: Vuelo bajo el cielo azul"
  },
  CollectionHall_90245_LockTip = {
    Text = "Completar el primer nivel del Paisaje onírico \"Más allá del horizonte (Parte 1)\" para desbloquear"
  },
  CollectionHall_90245_Title = {
    Text = "Antes de que el ave caiga"
  },
  CollectionHall_90415_Title = {
    Text = "Más allá del cielo · Parte 1"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:Breve introducción>\nUno de una serie de experimentos criados por la iglesia de la luz del templo para el ritual de invocación divina, tuvo la suerte de nacer como gemelo, lo que le evitó ser abandonado en un vertedero.\nDesde pequeños, él y su hermano gemelo, Pólux, fueron venerados como hijos sagrados y sometidos a una estricta disciplina, recibiendo constantemente enseñanzas teológicas sobre los portadores de la luz. El único contacto que tuvo con información externa fue un hermoso y grueso manuscrito ofrecido por un fiel seguidor.\nDurante su adolescencia, tras someter a su hermano a una cruel ceremonia de transformación por parte de la iglesia, ambos decidieron escapar juntos en busca de libertad, pero pronto fueron capturados nuevamente.\nÉl fue sumergido en una piscina de disolución llamada \"el charco del pecado\", donde fue sometido al \"tratamiento del pecado\" para sanar sus heridas, sufriendo largos tormentos.\nComo resultado, fue olvidado por todos excepto por Eliette, incluido Pólux, y la relación con su hermano se volvió tensa.\nDesde entonces, permaneció oculto, fingiendo obediencia hacia la iglesia, pero en su interior nunca abandonó la obsesión de escapar nuevamente con su hermano, esperando siempre una oportunidad para recuperar su libertad.\n\n."
  },
  CollectionHall_90416_LockTip = {
    Text = "Desbloquear tras despertar a \"Castor\""
  },
  CollectionHall_90416_Title = {Text = "Castor"},
  CollectionHall_94552_LockTip = {
    Text = "Necesitas superar cualquier fase del evento limitado en el tiempo «Gran conquista: Caza sagrada»"
  },
  CollectionHall_94552_Title = {
    Text = "Gran conquista: Caza sagrada"
  },
  CollectionHall_94553_Desc = {
    Text = "La iglesia de la luz del templo cultivó como experimento a un par de gemelos artificiales para el ritual de invocación divina. Justo cuando fue declarado un fracaso y estaba a punto de ser cruelmente abandonado, nació al separarse de la carne de su hermano. \n Aquella dependencia desesperada por sobrevivir no fue un privilegio, sino que transformó la tragedia breve de ambos en una tragedia aún más larga. \n Quizás debido al misterio de la gemelidad, su piel y carácter eran completamente opuestos a los de su hermano. Siendo el más activo e ingenioso de los gemelos, siempre realizaba actos rebeldes contrarios a la disciplina, como un chico travieso en una familia común—hasta que fue seleccionado para ser cultivado como recipiente divino y comenzó a someterse periódicamente a rituales de \"transformación sagrada\" dolorosos y sangrientos. \n Incapaz de soportar un destino desesperado por el dolor, tras suplicar y planear durante años junto a su hermano, finalmente lograron escapar superando numerosos peligros. \n Sin embargo, no pudieron disfrutar por mucho tiempo de su huida, pues fueron capturados nuevamente por los perseguidores de la iglesia. Úrsula ordenó que le arrancaran sus alas de libertad y lo sometió a un lavado de cerebro extremo, logrando que finalmente olvidara por completo a su hermano y comenzara a disfrutar de su rol como hijo sagrado, recibiendo la adoración de todos. \n Hasta que, tras una segunda huida, la muerte de su hermano y el efecto del ritual de invocación divina le devolvieron la memoria, encendiendo su \"corazón sagrado\" con odio y furia, y tomando como nueva dirección en su vida combatir contra la iglesia de la luz del templo."
  },
  CollectionHall_94553_LockTip = {
    Text = "Limpia el Paisaje onírico \"Más Allá del Horizonte: Inferior\" para desbloquear"
  },
  CollectionHall_94553_Title = {Text = "Pollux"},
  CollectionHall_95436_Desc = {
    Text = "Vuela, vuela, los pájaros usan sus alas para luchar contra la pesada gravedad, constantemente elevándose, elevándose, atravesando corrientes de aire turbulentas y remolinos, dirigiéndose hacia lugares más altos.\nSin embargo, él no sabe que un hilo invisible ha sido atado a sus pies; quizás nunca se ha convertido verdaderamente en un pájaro; incluso si vuela, es meramente una pobre cometa.\nAhora, la cuerda de la cometa se ha apretado."
  },
  CollectionHall_95436_LockTip = {
    Text = "Completa el Paisaje onírico \"Más allá del Horizonte: Superior\""
  },
  CollectionHall_95436_Title = {Text = "cometa"},
  CollectionHall_95437_Desc = {
    Text = "Viste esa cara, esa cara tierna, tranquila y hermosa.\nPronto se disolvió en tu memoria, pero siempre recordarás el color suave de la luz del amanecer tras la larga lluvia nocturna."
  },
  CollectionHall_95437_LockTip = {
    Text = "Completa el registro especial \"Sombra de la Ciudad Lluviosa\""
  },
  CollectionHall_95437_Title = {
    Text = "En las profundidades de la niebla de lluvia"
  },
  CollectionHall_95438_Desc = {
    Text = "Sé un gato, un gato despreocupado, solo quedándote con aquellos que amas, acurrucándote junto a ella todos los días para tomar el sol.\nEste es su hermoso pequeño sueño en el fondo, pero la belleza siempre sigue siendo una cosa tan frágil y delicada."
  },
  CollectionHall_95438_LockTip = {
    Text = "Completa el registro especial \"Fisión Tranquila\""
  },
  CollectionHall_95438_Title = {
    Text = "Deseo del gato"
  },
  CollectionHall_95439_Desc = {
    Text = "Incluso si el mundo se convierte en cenizas, incluso si todo se disuelve en D-baba, las inocentes medusas pueden sumergirse eternamente en sus propios sueños.\nAhí, todo es como era. Solo risas. Solo alegría."
  },
  CollectionHall_95439_LockTip = {
    Text = "Completa \"Todo como de costumbre\" en dificultad Difícil en El Errante"
  },
  CollectionHall_95439_Title = {
    Text = "Hundirse en la desbordante floración del Caos"
  },
  CollectionHall_95440_Desc = {
    Text = "Lentinium rara vez nieva en invierno; cada nevada desata la emoción y alegría de los niños. \n Despiertas de un sueño largo y suave y extiendes tu mano fuera de la ventana. Un copo de nieve cae en tu palma y se derrite gustosamente entre el calor. \n Los copos de nieve caen suavemente; tras un breve viaje por el cielo, regresan a la tierra, al río subterráneo, a casa y al ciclo de todas las gotas de agua. \n En la primera gran nevada de este año, otra ella también ha regresado a su hogar. \n Buenas noches, nieve; buenas noches, \"24\"."
  },
  CollectionHall_95440_LockTip = {
    Text = "Completa el registro especial \"Fisión Tranquila\""
  },
  CollectionHall_95440_Title = {
    Text = "Buenas noches, nieve"
  },
  CollectionHall_95441_Desc = {
    Text = "Las ramas de coral blanco se extienden hacia afuera, creciendo palacios de un blanco puro.\nEn las columnas distorsionadas, peces coloridos nadan libremente.\nEl cuerpo se hunde, el alma vaga.\nTú pierdes la respiración voluntariamente, hundiéndote junto a ella, perdido en un sueño blanco.\nEse es el milagro del mar, ese es el cálido azul de la patria."
  },
  CollectionHall_95441_LockTip = {
    Text = "Completa \"Esculpir una Canción\" en el vagar"
  },
  CollectionHall_95441_Title = {
    Text = "Palacio Puro"
  },
  CollectionHall_95442_Desc = {
    Text = "¡Ding ding——El pequeño tren parte!\nDéjame llevar a mis amigos al reino eterno de cuentos de hadas alegres sin dolor."
  },
  CollectionHall_95442_LockTip = {
    Text = "Completa \"Todo Como Siempre\" en la errancia"
  },
  CollectionHall_95442_Title = {
    Text = "Sueño inocente"
  },
  CollectionHall_95443_Desc = {
    Text = "¿Es ella la asesina? Parece una amante perdida desde hace mucho tiempo.\nLluvia, hojas muertas y un rastro de una fragancia floral soñadora; inspiras profundamente, tratando de captar un atisbo de sangre de esos olores húmedos como evidencia de su culpabilidad. Sin embargo, no olfateaste nada.\nElla nunca tuvo la intención de explicar, en medio de la neblina, te sumergiste en su sueño gris."
  },
  CollectionHall_95443_LockTip = {
    Text = "Completa el registro especial \"Sombra de la Ciudad Lluviosa\""
  },
  CollectionHall_95443_Title = {Text = "sospechoso"},
  CollectionHall_95444_Desc = {
    Text = "Esa misma sed también la ha experimentado ella.\nIngenua, salvaje y solitaria.\nTuvo suerte; ha terminado su larga vagancia, ganando recuerdos cálidos para saborear toda una vida.\nAhora toma la mano de un espíritu afín, enviando a esta alma errante a un sueño tranquilo."
  },
  CollectionHall_95444_LockTip = {
    Text = "Completa el registro especial \"Sombra de la Ciudad Lluviosa\" en dificultad Difícil"
  },
  CollectionHall_95444_Title = {
    Text = "Sueño de la bestia"
  },
  CollectionHall_95445_Desc = {
    Text = "Desde mi daga, acuchillándome el corazón.\nFrente al destino despiadado y a la vida amarga, soy tan pequeño, débil e impotente.\n¿Por qué debería ser yo? ¿Estoy haciéndolo bien como yo mismo?\nDe mis cuestionamientos, tampoco puedo responder."
  },
  CollectionHall_95445_LockTip = {
    Text = "Completa el registro especial \"Fisión Tranquila\""
  },
  CollectionHall_95445_Title = {
    Text = "Pregúntame"
  },
  CollectionHall_95446_Desc = {
    Text = "¿Eh? ¿Parece que eres diferente de hace un momento? \n¿Es que tus ojos son más brillantes? ¿O es que tu comportamiento es más animado? ¿O es que el dueño de esta mediocre envoltura ya ha cambiado su alma?"
  },
  CollectionHall_95446_LockTip = {
    Text = "Completa \"Esculpir una Canción\" en el vagar"
  },
  CollectionHall_95446_Title = {
    Text = "Transferencia del Alma"
  },
  CollectionHall_95447_Desc = {
    Text = "Pase lo que pase, ya sea nieve, lluvia, sol o nublado, el río sigue fluyendo tranquilamente hoy."
  },
  CollectionHall_95447_LockTip = {
    Text = "Completa el registro especial \"Fisión Tranquila\""
  },
  CollectionHall_95447_Title = {
    Text = "Río tranquilo"
  },
  CollectionHall_95448_Desc = {
    Text = "La marea sube, las cabezas gritan.\nParejas de ojos te miran, rostros te maldicen.\nQuieren ahogarte, quieren devorarte.\nCierras los ojos temerosamente, y cuando los abres de nuevo, te das cuenta de que están justo a tu lado."
  },
  CollectionHall_95448_LockTip = {
    Text = "Completa el registro especial \"Sombra de la Ciudad Lluviosa\""
  },
  CollectionHall_95448_Title = {
    Text = "Mar de cabezas"
  },
  CollectionHall_95449_Desc = {
    Text = "Ella te prometió que definitivamente te llevaría de vuelta a casa junto con ella. \n—Volver, con una actitud eterna, al hogar tranquilo, milagroso y hermoso."
  },
  CollectionHall_95449_LockTip = {
    Text = "Completa \"Esculpir una Canción\" en el vagar"
  },
  CollectionHall_95449_Title = {
    Text = "Arte de petrificación"
  },
  CollectionHall_95450_Desc = {
    Text = "Aquel ilustre huésped, mirando con esperanza la figura de Cástor, susurró bajo la luz de la luna la profecía del destino: \"Él saldrá adelante, luchará con desesperación en medio de la tormenta. Lo que lo haga elevarse, también lo hará caer\"."
  },
  CollectionHall_95450_LockTip = {
    Text = "Completa el Paisaje onírico \"Más allá del Horizonte: Superior\""
  },
  CollectionHall_95450_Title = {
    Text = "En el vendaval"
  },
  CollectionHall_95451_Desc = {
    Text = "Nacida en belleza, muriendo en belleza.\nElla es una genio, una mujer loca, un diablo; ella es la despiadada verduga, y también tu tierna familia.\nCon amor ferviente, te convierte en una obra maestra perfecta.\nElla te abraza, toma tu mano fría. Ella te llevará de regreso a la patria del arte con ella"
  },
  CollectionHall_95451_LockTip = {
    Text = "Completa \"Esculpiendo una Canción\" en dificultad Difícil en El Errante"
  },
  CollectionHall_95451_Title = {
    Text = "Muerte de la belleza"
  },
  CollectionHall_95452_Desc = {
    Text = "El océano escuchó mi llamado, trayéndote así a mi lado.\nDesde entonces, hemos hablado, jugado y alegrado libremente, destinados a convertirnos en los mejores amigos del mundo.\nEn esta ciudad llena de disolución y silencio mortal."
  },
  CollectionHall_95452_LockTip = {
    Text = "Completa \"Todo Como Siempre\" en la errancia"
  },
  CollectionHall_95452_Title = {
    Text = "Sé mi amigo"
  },
  CollectionHall_95453_Desc = {
    Text = "Regresa, todas las versiones valientes, cobardes, inteligentes, tontas, fuertes y débiles de mí.\nDeja que todos los corazones alegres, tristes, enojados, doloridos y cansados se derritan.\nEstamos juntos.\nEllos están juntos para siempre."
  },
  CollectionHall_95453_LockTip = {
    Text = "Completa el registro especial \"Fisión Tranquila\" en dificultad Difícil"
  },
  CollectionHall_95453_Title = {
    Text = "Vuelve a ella"
  },
  CollectionHall_95454_Desc = {
    Text = "Este vacío y las grietas provenientes del alma solo pueden ser llenados por el cuento de hadas más puro.\nAlgún día, ella dirá adiós al dolor y regresará al \"hogar\" lleno de alegría del cuento de hadas."
  },
  CollectionHall_95454_LockTip = {
    Text = "Completa \"Todo Como Siempre\" en la errancia"
  },
  CollectionHall_95454_Title = {
    Text = "Cuento de terror inocente"
  },
  CollectionHall_95455_Desc = {
    Text = "Esos callejones oscuros y estrechos, acechando con la oscuridad, siempre llevan muchos momentos de puntos de inflexión del destino. Reuniones, peleas, separaciones, incluso violencia, acoso y asesinato.\nAfortunadamente, la historia de hoy no incluyó las escenas sangrientas de la parte final, pero ¿quién puede decir que lo que precedió no llevó a una verdadera tragedia?"
  },
  CollectionHall_95455_LockTip = {
    Text = "Completa el Paisaje onírico \"Más allá del Horizonte: Superior\""
  },
  CollectionHall_95455_Title = {
    Text = "callejón oscuro"
  },
  CollectionHall_95469_LockTip = {
    Text = "Reclama la recompensa del Día 1 en el Evento por Tiempo Limitado \"Verano Eterno bajo el Sol Negro: Celebración de Verano toda la Noche\""
  },
  CollectionHall_95469_Title = {
    Text = "Verano bajo el sol negro"
  },
