  },
  CollectionHall_96790_Title = {
    Text = "El banquete del rey"
  },
  CollectionHall_97150_LockTip = {
    Text = "Necesitas completar cualquier fase del evento por tiempo limitado \"Lado oscuro del lienzo: Papiro de otro mundo\""
  },
  CollectionHall_97150_Title = {
    Text = "Lado oscuro del lienzo: Mapa del más allá"
  },
