    Text = "Es necesario completar cualquier fase del evento por tiempo limitado \"La caída de la luz infinita: Caza de cenizas apagadas\""
  },
  CollectionHall_97158_Title = {
    Text = "La deslumbrante caída de luz de innumerables mundos: Caza de cenizas apagadas"
  },
  CollectionHall_97208_LockTip = {
    Text = "Completar el errante \"Pintura de aberración\" para desbloquear la primera etapa"
  },
  CollectionHall_97208_Title = {
    Text = "El verdadero arte"
  },
